    10	use crate::error::{Error, ErrorCode, Result};
    11	use crate::queue::Queue;
    12	use crate::request::{Params, Request};
    13	
    14	/// Largest `Seconds` accepted by `Tick`.
    15	const MAX_TICK: u64 = 1_209_600;
    16	
    17	/// Result members of a successful command (the `ok` member is added later).
    18	type Members = Map<String, Value>;
    19	
    20	/// The whole service state. Time is virtual and only `Tick` moves it.
    21	pub struct Broker {
    22	    now: u64,
    23	    /// The next number for `MessageId` (`m-<n>`), counted over all queues.
    24	    next_message_id: u64,
    25	    /// The next number for `ReceiptHandle` (`r-<n>`), counted over all queues.
    26	    next_receipt_handle: u64,
    27	    /// Ordered by name, which is the order `ListQueues` needs.
    28	    queues: BTreeMap<String, Queue>,
    29	}
    30	
    31	impl Default for Broker {
    32	    fn default() -> Self {
    33	        Self {
    34	            now: 0,
    35	            next_message_id: 1,
    36	            next_receipt_handle: 1,
    37	            queues: BTreeMap::new(),
    38	        }
    39	    }
    40	}
    41	
    42	impl Broker {
    43	    pub fn new() -> Self {
    44	        Self::default()
    45	    }
    46	
    47	    /// Runs one command line (without its newline) and returns the response
    48	    /// line (without its newline).
    49	    pub fn handle_line(&mut self, line: &[u8]) -> String {
    50	        let response = match Request::parse(line).and_then(|req| self.dispatch(&req)) {
    51	            Ok(mut members) => {
    52	                members.insert("ok".into(), Value::Bool(true));
    53	                Value::Object(members)
    54	            }
    55	            Err(Error { code, message }) => json!({
    56	                "ok": false,
    57	                "error": { "code": code.as_str(), "message": message },
    58	            }),
    59	        };
    60	        response.to_string()
    61	    }
    62	
    63	    fn dispatch(&mut self, req: &Request) -> Result<Members> {
    64	        let params = req.params();
    65	        match req.command.as_str() {
    66	            "CreateQueue" => self.create_queue(params),
    67	            "SetQueueAttributes" => self.set_queue_attributes(params),
    68	            "GetQueueAttributes" => self.get_queue_attributes(params),
    69	            "ListQueues" => self.list_queues(params),
    70	            "DeleteQueue" => self.delete_queue(params),
    71	            "PurgeQueue" => self.purge_queue(params),
    72	            "SendMessage" => self.send_message(params),
    73	            "ReceiveMessage" => self.receive_message(params),
    74	            "DeleteMessage" => self.delete_message(params),
    75	            "ChangeMessageVisibility" => self.change_message_visibility(params),
    76	            "Tick" => self.tick(params),
    77	            other => Err(Error::new(
    78	                ErrorCode::InvalidRequest,
    79	                format!("unknown command `{other}`"),
    80	            )),
    81	        }
    82	    }
    83	
    84	    fn tick(&mut self, params: Params<'_>) -> Result<Members> {
    85	        params.require(&["Seconds"])?;
    86	        let seconds = params.integer("Seconds", 0..=MAX_TICK)?.expect("required");
    87	        self.now += seconds;
    88	        Ok(members([("Now", json!(self.now))]))
    89	    }
    90	
    91	    /// Looks up a queue (SPEC section 2, check 4) with expired messages
    92	    /// already removed.
    93	    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
    94	        lookup(&mut self.queues, self.now, name)
    95	    }
    96	}
    97	
    98	/// [`Broker::queue_mut`] on the queue map alone, for callers that need to
    99	/// touch other broker fields while holding the queue.
   100	fn lookup<'a>(
   101	    queues: &'a mut BTreeMap<String, Queue>,
   102	    now: u64,
   103	    name: &str,
   104	) -> Result<&'a mut Queue> {
   105	    let queue = queues.get_mut(name).ok_or_else(|| does_not_exist(name))?;
   106	    queue.expire(now);
   107	    Ok(queue)
   108	}
   109	
   110	fn does_not_exist(name: &str) -> Error {
   111	    Error::new(
   112	        ErrorCode::QueueDoesNotExist,
   113	        format!("queue `{name}` does not exist"),
   114	    )
   115	}
   116	
   117	/// Builds a result member map from name/value pairs.
   118	fn members<const N: usize>(pairs: [(&str, Value); N]) -> Members {
   119	    pairs.into_iter().map(|(k, v)| (k.to_owned(), v)).collect()
   120	}
