     1	//! Message commands (SPEC section 6).
     2	
     3	use serde_json::{Value, json};
     4	
     5	use super::{Broker, Members, lookup, members};
     6	use crate::error::{Error, ErrorCode, Result};
     7	use crate::queue::{Accepted, MAX_MESSAGES, Message, Step};
     8	use crate::request::Params;
     9	
    10	const MAX_BODY_BYTES: usize = 1024;
    11	const MAX_ID_CHARS: usize = 128;
    12	
    13	fn message_id(n: u64) -> String {
    14	    format!("m-{n}")
    15	}
    16	
    17	fn receipt_handle(n: u64) -> String {
    18	    format!("r-{n}")
    19	}
    20	
    21	fn unsupported(message: &str) -> Error {
    22	    Error::new(ErrorCode::UnsupportedOperation, message)
    23	}
    24	
    25	fn missing(name: &str) -> Error {
    26	    Error::new(ErrorCode::MissingParameter, format!("`{name}` is required"))
    27	}
    28	
    29	/// Parses `r-<n>` exactly as it was issued: no sign, no leading zeros.
    30	fn parse_receipt_handle(text: &str) -> Option<u64> {
    31	    let digits = text.strip_prefix("r-")?;
    32	    if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
    33	        return None;
    34	    }
    35	    digits.parse().ok()
    36	}
    37	
    38	fn received_json(message: &Message, handle: u64, fifo: bool) -> Value {
    39	    let mut json = json!({
    40	        "MessageId": message_id(message.id),
    41	        "ReceiptHandle": receipt_handle(handle),
    42	        "Body": message.body,
    43	        "ReceiveCount": message.receive_count,
    44	        "SentAt": message.sent_at,
    45	        "FirstReceivedAt": message.first_received_at,
    46	    });
    47	    if fifo {
    48	        json["GroupId"] = json!(message.group_id);
    49	        json["SequenceNumber"] = json!(message.sequence_number);
    50	    }
    51	    json
    52	}
    53	
    54	impl Broker {
    55	    pub(super) fn send_message(&mut self, params: Params<'_>) -> Result<Members> {
    56	        params.require(&["QueueName", "Body"])?;
    57	        let name = params.string("QueueName")?.expect("required");
    58	        let body = params.string("Body")?.expect("required");
    59	        if !(1..=MAX_BODY_BYTES).contains(&body.len()) {
    60	            return Err(Error::new(
    61	                ErrorCode::InvalidParameterValue,
    62	                format!("`Body` must be 1 to {MAX_BODY_BYTES} bytes"),
    63	            ));
    64	        }
    65	        let delay = params.integer("DelaySeconds", 0..=900)?;
    66	        let group_id = params.identifier("GroupId", MAX_ID_CHARS)?;
    67	        let deduplication_id = params.identifier("DeduplicationId", MAX_ID_CHARS)?;
    68	
    69	        let now = self.now;
    70	        let queue = lookup(&mut self.queues, now, name)?;
    71	        let attributes = &queue.attributes;
    72	        if !attributes.fifo && (group_id.is_some() || deduplication_id.is_some()) {
    73	            return Err(unsupported(
    74	                "`GroupId` and `DeduplicationId` need a FIFO queue",
    75	            ));
    76	        }
    77	        if attributes.fifo && delay.is_some() {
    78	            return Err(unsupported("FIFO queues do not support per-message delay"));
    79	        }
    80	        let fifo_ids = if attributes.fifo {
    81	            let group_id = group_id.ok_or_else(|| missing("GroupId"))?;
    82	            let deduplication_id = match deduplication_id {
    83	                Some(id) => id,
    84	                None if attributes.content_based_deduplication => body,
    85	                None => return Err(missing("DeduplicationId")),
    86	            };
    87	            if let Some(original) = queue.duplicate_of(deduplication_id, now) {
    88	                return Ok(members([
    89	                    ("MessageId", json!(message_id(original.message_id))),
    90	                    ("SequenceNumber", json!(original.sequence_number)),
    91	                ]));
    92	            }
    93	            Some((group_id, deduplication_id))
    94	        } else {
    95	            None
    96	        };
    97	        if queue.len() >= MAX_MESSAGES {
    98	            return Err(Error::new(
    99	                ErrorCode::LimitExceeded,
   100	                format!("a queue holds at most {MAX_MESSAGES} messages"),
   101	            ));
   102	        }
   103	
   104	        let id = self.next_message_id;
   105	        self.next_message_id += 1;
   106	        let delay = delay.unwrap_or(queue.attributes.delay_seconds);
   107	        let sequence_number = queue.push(Message {
   108	            id,
   109	            body: body.to_owned(),
   110	            sent_at: now,
   111	            receive_count: 0,
   112	            first_received_at: None,
   113	            group_id: fifo_ids.map(|(group, _)| group.to_owned()),
   114	            sequence_number: None,
   115	            delayed_until: now + delay,
   116	            invisible_until: 0,
   117	            handle: None,
   118	        });
   119	        let mut result = members([("MessageId", json!(message_id(id)))]);
   120	        if let (Some((_, deduplication_id)), Some(sequence_number)) = (fifo_ids, sequence_number) {
   121	            queue.record_deduplication(
   122	                deduplication_id,
   123	                Accepted {
   124	                    accepted_at: now,
   125	                    message_id: id,
   126	                    sequence_number,
   127	                },
   128	            );
   129	            result.insert("SequenceNumber".into(), json!(sequence_number));
   130	        }
   131	        Ok(result)
   132	    }
   133	
   134	    pub(super) fn receive_message(&mut self, params: Params<'_>) -> Result<Members> {
   135	        params.require(&["QueueName"])?;
   136	        let name = params.string("QueueName")?.expect("required");
   137	        let max_messages = params.integer("MaxMessages", 1..=10)?.unwrap_or(1);
   138	        let visibility_timeout = params.integer("VisibilityTimeout", 0..=43_200)?;
   139	
   140	        let now = self.now;
   141	        let mut next_handle = self.next_receipt_handle;
   142	        let queue = lookup(&mut self.queues, now, name)?;
   143	        let visibility_timeout = visibility_timeout.unwrap_or(queue.attributes.visibility_timeout);
   144	        let fifo = queue.attributes.fifo;
   145	        let dead_letter_queue = queue
   146	            .attributes
   147	            .dead_letter
   148	            .as_ref()
   149	            .map(|dl| dl.queue.clone());
   150	
   151	        let mut delivered = Vec::new();
   152	        let mut dead_letters = Vec::new();
   153	        for step in queue.plan_receive(now, max_messages as usize) {
   154	            match step {
   155	                Step::Deliver(key) => {
   156	                    let handle = next_handle;
   157	                    next_handle += 1;
   158	                    let message = queue.deliver(key, now, visibility_timeout, handle);
   159	                    delivered.push(received_json(message, handle, fifo));
   160	                }
   161	                Step::DeadLetter(key) => {
   162	                    dead_letters.extend(queue.remove(key));
   163	                }
   164	            }
   165	        }
   166	        self.next_receipt_handle = next_handle;
   167	
   168	        if let Some(target) = dead_letter_queue.and_then(|q| self.queues.get_mut(&q)) {
   169	            for message in dead_letters {
   170	                target.push_dead_letter(message, now);
   171	            }
   172	        }
   173	        Ok(members([("Messages", Value::Array(delivered))]))
   174	    }
   175	
   176	    pub(super) fn delete_message(&mut self, params: Params<'_>) -> Result<Members> {
   177	        params.require(&["QueueName", "ReceiptHandle"])?;
   178	        let name = params.string("QueueName")?.expect("required");
   179	        let handle = params.string("ReceiptHandle")?.expect("required");
   180	
   181	        let key = self.in_flight_message(name, handle)?;
   182	        self.queue_mut(name)?.remove(key);
   183	        Ok(Members::new())
   184	    }
   185	
   186	    pub(super) fn change_message_visibility(&mut self, params: Params<'_>) -> Result<Members> {
   187	        params.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
   188	        let name = params.string("QueueName")?.expect("required");
