1	//! A single queue: its attributes, messages and bookkeeping.
2	//!
3	//! The queue knows nothing about other queues or the clock's owner; the
4	//! broker passes `now` in and coordinates dead-letter moves.
5	
6	use std::collections::{BTreeMap, HashMap, HashSet};
7	
8	use crate::attributes::Attributes;
9	
10	pub const MAX_MESSAGES: usize = 100_000;
11	const DEDUP_WINDOW: u64 = 300;
12	const MIN_DEDUP_PRUNE_LEN: usize = 1024;
13	
14	#[derive(Clone, Debug)]
15	pub struct Message {
16	    pub id: u64,
17	    pub body: String,
18	    pub sent_at: u64,
19	    pub receive_count: u64,
20	    pub first_received_at: Option<u64>,
21	    pub group_id: Option<String>,
22	    pub sequence_number: Option<u64>,
23	    /// The message is delayed while `now < delayed_until`.
24	    pub delayed_until: u64,
25	    /// The message is in flight while `now < invisible_until`.
26	    pub invisible_until: u64,
27	    /// The latest receipt handle issued for this message.
28	    pub handle: Option<u64>,
29	}
30	
31	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
32	pub enum State {
33	    Delayed,
34	    InFlight,
35	    Visible,
36	}
37	
38	impl Message {
39	    pub fn state(&self, now: u64) -> State {
40	        if now < self.delayed_until {
41	            State::Delayed
42	        } else if now < self.invisible_until {
43	            State::InFlight
44	        } else {
45	            State::Visible
46	        }
47	    }
48	}
49	
50	/// What `ReceiveMessage` does with one examined message.
51	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
52	pub enum Step {
53	    Deliver(u64),
54	    DeadLetter(u64),
55	}
56	
57	#[derive(Clone, Copy, Debug, Default)]
58	pub struct Counts {
59	    pub visible: u64,
60	    pub in_flight: u64,
61	    pub delayed: u64,
62	}
63	
64	/// The original message of a deduplication id.
65	#[derive(Clone, Copy, Debug)]
66	pub struct Accepted {
67	    pub accepted_at: u64,
68	    pub message_id: u64,
69	    pub sequence_number: u64,
70	}
71	
72	pub struct Queue {
73	    pub attributes: Attributes,
74	    /// Messages in arrival order, keyed by an ever-growing arrival index.
75	    messages: BTreeMap<u64, Message>,
76	    next_arrival: u64,
77	    /// Latest receipt handle -> arrival index of its message.
78	    handles: HashMap<u64, u64>,
79	    next_sequence: u64,
80	    deduplication: HashMap<String, Accepted>,
81	    prune_deduplication_at: usize,
82	    /// A lower bound of the `sent_at` of all messages, to skip needless sweeps.
83	    oldest_sent_at: Option<u64>,
84	}
85	
86	impl Queue {
87	    pub fn new(attributes: Attributes) -> Self {
88	        Self {
89	            attributes,
90	            messages: BTreeMap::new(),
91	            next_arrival: 0,
92	            handles: HashMap::new(),
93	            next_sequence: 1,
94	            deduplication: HashMap::new(),
95	            prune_deduplication_at: MIN_DEDUP_PRUNE_LEN,
96	            oldest_sent_at: None,
97	        }
98	    }
99	
100	    pub fn len(&self) -> usize {
101	        self.messages.len()
102	    }
103	
104	    /// Removes the messages whose retention has run out.
105	    pub fn expire(&mut self, now: u64) {
106	        let retention = self.attributes.retention_seconds;
107	        let is_expired = |m: &Message| now >= m.sent_at + retention;
108	        if !self.oldest_sent_at.is_some_and(|t| now >= t + retention) {
109	            return;
110	        }
111	        let expired: Vec<u64> = self
112	            .messages
113	            .iter()
114	            .filter(|(_, m)| is_expired(m))
115	            .map(|(&key, _)| key)
116	            .collect();
117	        for key in expired {
118	            self.remove(key);
119	        }
120	        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min();
121	    }
122	
123	    pub fn counts(&self, now: u64) -> Counts {
124	        let mut counts = Counts::default();
125	        for message in self.messages.values() {
126	            match message.state(now) {
127	                State::Visible => counts.visible += 1,
128	                State::InFlight => counts.in_flight += 1,
129	                State::Delayed => counts.delayed += 1,
130	            }
131	        }
132	        counts
133	    }
134	
135	    /// Removes every message. Sequence numbers and deduplication carry on.
136	    pub fn purge(&mut self) {
137	        self.messages.clear();
138	        self.handles.clear();
139	        self.oldest_sent_at = None;
140	    }
141	
142	    /// Adds a message at the end of the queue and returns its sequence number
143	    /// if this is a FIFO queue.
144	    pub fn push(&mut self, mut message: Message) -> Option<u64> {
145	        message.sequence_number = self.attributes.fifo.then(|| {
146	            let sequence = self.next_sequence;
147	            self.next_sequence += 1;
148	            sequence
149	        });
150	        let sequence = message.sequence_number;
151	        self.oldest_sent_at = Some(
152	            self.oldest_sent_at
153	                .map_or(message.sent_at, |t| t.min(message.sent_at)),
154	        );
155	        self.messages.insert(self.next_arrival, message);
156	        self.next_arrival += 1;
157	        sequence
158	    }
159	
160	    /// Adds a message moved here from another queue's dead-letter handling.
161	    pub fn push_dead_letter(&mut self, mut message: Message, now: u64) {
162	        message.receive_count = 0;
163	        message.first_received_at = None;
164	        message.delayed_until = 0;
165	        message.invisible_until = 0;
166	        message.handle = None;
167	        self.push(message);
168	        self.expire(now);
169	    }
170	
171	    /// Removes and returns the message with this arrival index.
172	    pub fn remove(&mut self, key: u64) -> Option<Message> {
173	        let message = self.messages.remove(&key)?;
174	        if let Some(handle) = message.handle {
175	            self.handles.remove(&handle);
176	        }
177	        Some(message)
178	    }
179	
180	    /// The arrival index of the message that is in flight right now and whose
181	    /// latest handle is `handle`.
182	    pub fn find_in_flight(&self, handle: u64, now: u64) -> Option<u64> {
183	        let key = *self.handles.get(&handle)?;
184	        let message = self.messages.get(&key)?;
185	        (message.state(now) == State::InFlight).then_some(key)
186	    }
187	
188	    pub fn message_mut(&mut self, key: u64) -> Option<&mut Message> {
189	        self.messages.get_mut(&key)
190	    }
191	
192	    /// Examines the messages as `ReceiveMessage` does (SPEC section 6) and
193	    /// says what to do with each one; it changes nothing.
194	    pub fn plan_receive(&self, now: u64, max_messages: usize) -> Vec<Step> {
195	        let mut steps = Vec::new();
196	        let mut delivered = 0;
197	        // Groups that still have an earlier message in the queue.
198	        let mut blocked: HashSet<&str> = HashSet::new();
199	        for (&key, message) in &self.messages {
200	            let group = message.group_id.as_deref();
201	            if group.is_some_and(|g| blocked.contains(g)) {
202	                continue;
203	            }
204	            if message.state(now) != State::Visible {
205	                blocked.extend(group);
206	                continue;
207	            }
208	            match &self.attributes.dead_letter {
209	                Some(dl) if message.receive_count >= dl.max_receive_count => {
210	                    steps.push(Step::DeadLetter(key));
211	                }
212	                _ => {
213	                    steps.push(Step::Deliver(key));
214	                    blocked.extend(group);
215	                    delivered += 1;
216	                    if delivered == max_messages {
217	                        break;
218	                    }
219	                }
220	            }
221	        }
222	        steps
223	    }
224	
225	    /// Delivers a message: it is now in flight for `visibility_timeout`
226	    /// seconds under the new receipt `handle`.
227	    pub fn deliver(
228	        &mut self,
229	        key: u64,
230	        now: u64,
231	        visibility_timeout: u64,
232	        handle: u64,
233	    ) -> &Message {
234	        let message = self.messages.get_mut(&key).expect("planned message exists");
235	        if let Some(old) = message.handle.replace(handle) {
236	            self.handles.remove(&old);
237	        }
238	        self.handles.insert(handle, key);
239	        message.receive_count += 1;
240	        message.first_received_at.get_or_insert(now);
241	        message.invisible_until = now + visibility_timeout;
242	        message
243	    }
244	
245	    /// The original send of this deduplication id, if its window is open.
246	    pub fn duplicate_of(&self, deduplication_id: &str, now: u64) -> Option<Accepted> {
247	        self.deduplication
248	            .get(deduplication_id)
249	            .filter(|a| now - a.accepted_at < DEDUP_WINDOW)
250	            .copied()
251	    }
252	
253	    /// Opens a deduplication window for an accepted send.
254	    pub fn record_deduplication(&mut self, deduplication_id: &str, accepted: Accepted) {
255	        if self.deduplication.len() >= self.prune_deduplication_at {
256	            let now = accepted.accepted_at;
