1	//! Parsing of command lines and typed access to their parameters.
2	//!
3	//! Parameter access follows the check order of SPEC section 2: a handler
4	//! first calls [`Params::require`] for all required names, then reads each
5	//! value with a typed getter, which reports `InvalidParameterValue`.
6	
7	use std::ops::RangeInclusive;
8	
9	use serde_json::{Map, Value};
10	
11	use crate::error::{Error, ErrorCode, Result};
12	use crate::naming;
13	
14	/// A parsed command line: the command name and its parameter object.
15	pub struct Request {
16	    pub command: String,
17	    pub members: Map<String, Value>,
18	}
19	
20	impl Request {
21	    /// Checks the request shape (SPEC section 2, check 1).
22	    pub fn parse(line: &[u8]) -> Result<Self> {
23	        let invalid = |msg: &str| Error::new(ErrorCode::InvalidRequest, msg);
24	        let text = std::str::from_utf8(line).map_err(|_| invalid("line is not valid UTF-8"))?;
25	        let value: Value =
26	            serde_json::from_str(text).map_err(|e| invalid(&format!("invalid JSON: {e}")))?;
27	        let Value::Object(members) = value else {
28	            return Err(invalid("request is not a JSON object"));
29	        };
30	        let command = match members.get("Command") {
31	            Some(Value::String(name)) => name.clone(),
32	            _ => return Err(invalid("`Command` is missing or not a string")),
33	        };
34	        Ok(Self { command, members })
35	    }
36	
37	    pub fn params(&self) -> Params<'_> {
38	        Params::new(&self.members)
39	    }
40	}
41	
42	/// Read-only typed view of a JSON object. `null` members count as absent.
43	#[derive(Clone, Copy)]
44	pub struct Params<'a> {
45	    members: &'a Map<String, Value>,
46	}
47	
48	fn invalid_value(name: &str, expected: &str) -> Error {
49	    Error::new(
50	        ErrorCode::InvalidParameterValue,
51	        format!("`{name}` must be {expected}"),
52	    )
53	}
54	
55	impl<'a> Params<'a> {
56	    pub fn new(members: &'a Map<String, Value>) -> Self {
57	        Self { members }
58	    }
59	
60	    fn get(&self, name: &str) -> Option<&'a Value> {
61	        self.members.get(name).filter(|v| !v.is_null())
62	    }
63	
64	    pub fn has(&self, name: &str) -> bool {
65	        self.get(name).is_some()
66	    }
67	
68	    /// Fails with `MissingParameter` for the first absent name.
69	    pub fn require(&self, names: &[&str]) -> Result<()> {
70	        match names.iter().find(|name| !self.has(name)) {
71	            Some(name) => Err(Error::new(
72	                ErrorCode::MissingParameter,
73	                format!("`{name}` is required"),
74	            )),
75	            None => Ok(()),
76	        }
77	    }
78	
79	    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
80	        self.get(name)
81	            .map(|v| v.as_str().ok_or_else(|| invalid_value(name, "a string")))
82	            .transpose()
83	    }
84	
85	    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
86	        self.get(name)
87	            .map(|v| v.as_bool().ok_or_else(|| invalid_value(name, "a boolean")))
88	            .transpose()
89	    }
90	
91	    /// An integer written without fraction or exponent, within `range`.
92	    pub fn integer(&self, name: &str, range: RangeInclusive<u64>) -> Result<Option<u64>> {
93	        let Some(value) = self.get(name) else {
94	            return Ok(None);
95	        };
96	        let number = value
97	            .as_number()
98	            .and_then(|n| n.as_i64())
99	            .ok_or_else(|| invalid_value(name, "an integer"))?;
100	        u64::try_from(number)
101	            .ok()
102	            .filter(|n| range.contains(n))
103	            .map(Some)
104	            .ok_or_else(|| {
105	                invalid_value(
106	                    name,
107	                    &format!("between {} and {}", range.start(), range.end()),
108	                )
109	            })
110	    }
111	
112	    /// A string of 1 to `max_len` characters from `A-Z a-z 0-9 _ -`.
113	    pub fn identifier(&self, name: &str, max_len: usize) -> Result<Option<&'a str>> {
114	        match self.string(name)? {
115	            Some(s) if !naming::is_identifier(s, max_len) => Err(invalid_value(
116	                name,
117	                &format!("1 to {max_len} characters from A-Z a-z 0-9 _ -"),
118	            )),
119	            other => Ok(other),
120	        }
121	    }
122	
123	    pub fn object(&self, name: &str) -> Result<Option<Params<'a>>> {
124	        self.get(name)
125	            .map(|v| {
126	                v.as_object()
127	                    .map(Params::new)
128	                    .ok_or_else(|| invalid_value(name, "an object"))
129	            })
130	            .transpose()
131	    }
132	
133	    /// Fails with `InvalidParameterValue` if a member is not in `known`.
134	    pub fn reject_unknown(&self, known: &[&str]) -> Result<()> {
135	        match self.members.keys().find(|k| !known.contains(&k.as_str())) {
136	            Some(key) => Err(Error::new(
137	                ErrorCode::InvalidParameterValue,
138	                format!("unknown attribute `{key}`"),
139	            )),
140	            None => Ok(()),
141	        }
142	    }
