1	//! Queue management commands (SPEC section 5).
2	
3	use serde_json::json;
4	
5	use super::{Broker, Members, does_not_exist, members};
6	use crate::attributes::{AttributeUpdate, Attributes};
7	use crate::error::{Error, ErrorCode, Result};
8	use crate::naming;
9	use crate::queue::Queue;
10	use crate::request::Params;
11	
12	const MAX_QUEUES: usize = 1000;
13	
14	fn invalid_value(message: &str) -> Error {
15	    Error::new(ErrorCode::InvalidParameterValue, message)
16	}
17	
18	/// Reads the `QueueName` every queue command takes.
19	fn queue_name<'a>(params: Params<'a>) -> Result<&'a str> {
20	    params.require(&["QueueName"])?;
21	    Ok(params.string("QueueName")?.expect("required"))
22	}
23	
24	impl Broker {
25	    pub(super) fn create_queue(&mut self, params: Params<'_>) -> Result<Members> {
26	        let name = queue_name(params)?;
27	        if !naming::is_valid_queue_name(name) {
28	            return Err(Error::new(
29	                ErrorCode::QueueNameInvalid,
30	                format!("`{name}` is not a valid queue name"),
31	            ));
32	        }
33	        let update = AttributeUpdate::parse(params.object("Attributes")?)?;
34	
35	        let fifo = update.fifo.unwrap_or(false);
36	        if naming::has_fifo_suffix(name) != fifo {
37	            return Err(Error::new(
38	                ErrorCode::QueueNameInvalid,
39	                "the `.fifo` suffix and the `Fifo` attribute must agree",
40	            ));
41	        }
42	        if update.content_based_deduplication == Some(true) && !fifo {
43	            return Err(invalid_value(
44	                "`ContentBasedDeduplication` requires a FIFO queue",
45	            ));
46	        }
47	        update.dead_letter()?;
48	
49	        let mut attributes = Attributes::default();
50	        attributes.apply(update);
51	
52	        if let Some(existing) = self.queues.get(name) {
53	            return if existing.attributes == attributes {
54	                Ok(Members::new())
55	            } else {
56	                Err(Error::new(
57	                    ErrorCode::QueueAlreadyExists,
58	                    format!("queue `{name}` exists with different attributes"),
59	                ))
60	            };
61	        }
62	        if let Some(dead_letter) = &attributes.dead_letter {
63	            let target = self
64	                .queues
65	                .get(&dead_letter.queue)
66	                .ok_or_else(|| does_not_exist(&dead_letter.queue))?;
67	            if target.attributes.fifo != fifo {
68	                return Err(invalid_value(
69	                    "the dead-letter queue must be of the same type",
70	                ));
71	            }
72	        }
73	        if self.queues.len() >= MAX_QUEUES {
74	            return Err(Error::new(
75	                ErrorCode::LimitExceeded,
76	                format!("at most {MAX_QUEUES} queues may exist"),
77	            ));
78	        }
79	        self.queues.insert(name.to_owned(), Queue::new(attributes));
80	        Ok(Members::new())
81	    }
82	
83	    pub(super) fn set_queue_attributes(&mut self, params: Params<'_>) -> Result<Members> {
84	        params.require(&["QueueName", "Attributes"])?;
85	        let name = params.string("QueueName")?.expect("required");
86	        let update = AttributeUpdate::parse(params.object("Attributes")?)?;
87	        let fifo = self.queue_mut(name)?.attributes.fifo;
88	
89	        if update.fifo.is_some() {
90	            return Err(Error::new(
91	                ErrorCode::UnsupportedOperation,
92	                "the type of a queue cannot change",
93	            ));
94	        }
95	        if update.content_based_deduplication == Some(true) && !fifo {
96	            return Err(invalid_value(
97	                "`ContentBasedDeduplication` requires a FIFO queue",
98	            ));
99	        }
100	        if let Some(dead_letter) = update.dead_letter()? {
101	            let target = self
102	                .queues
103	                .get(&dead_letter.queue)
104	                .ok_or_else(|| does_not_exist(&dead_letter.queue))?;
105	            if dead_letter.queue == name || target.attributes.fifo != fifo {
106	                return Err(invalid_value(
107	                    "the dead-letter queue must be another queue of the same type",
108	                ));
109	            }
110	        }
111	
112	        let now = self.now;
113	        let queue = self.queue_mut(name)?;
114	        queue.attributes.apply(update);
115	        queue.expire(now);
116	        Ok(Members::new())
117	    }
118	
119	    pub(super) fn get_queue_attributes(&mut self, params: Params<'_>) -> Result<Members> {
120	        let name = queue_name(params)?;
121	        let now = self.now;
122	        let queue = self.queue_mut(name)?;
123	        let counts = queue.counts(now);
124	        Ok(members([
125	            ("Attributes", queue.attributes.to_json()),
126	            (
127	                "Counts",
128	                json!({
129	                    "Visible": counts.visible,
130	                    "InFlight": counts.in_flight,
